{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    if goal <= 0 or bucket_one <= 0 or bucket_two <= 0:
        raise ValueError("bucket sizes and goal must be positive")
    if goal > max(bucket_one, bucket_two):
        raise ValueError("goal is larger than both buckets")

    sizes = (bucket_one, bucket_two)
    start = (bucket_one, 0) if start_bucket == "one" else (0, bucket_two)

    def forbidden(state):
        if start_bucket == "one":
            return state[0] == 0 and state[1] == bucket_two
        return state[1] == 0 and state[0] == bucket_one

    def neighbours(state):
        a, b = state
        cap_a, cap_b = sizes
        pour_ab = min(a, cap_b - b)
        pour_ba = min(b, cap_a - a)
        yield (cap_a, b)
        yield (a, cap_b)
        yield (0, b)
        yield (a, 0)
        yield (a - pour_ab, b + pour_ab)
        yield (a + pour_ba, b - pour_ba)

    seen = {start}
    queue = deque([(start, 1)])
    while queue:
        state, moves = queue.popleft()
        if state[0] == goal:
            return moves, "one", state[1]
        if state[1] == goal:
            return moves, "two", state[0]
        for nxt in neighbours(state):
            if nxt in seen or forbidden(nxt):
                continue
            seen.add(nxt)
            queue.append((nxt, moves + 1))

    raise ValueError("goal cannot be reached with these buckets")
"}

